import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DashboardLayout from './DashboardLayout';

const WalletPage = () => {
  const user = JSON.parse(localStorage.getItem('vrx_user') || '{}');
  const [balance, setBalance] = useState(user.walletBalance || 0);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [addAmount, setAddAmount] = useState('');
  const [adding, setAdding] = useState(false);
  const [message, setMessage] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('upi');

  const fetchWallet = () => {
    if (!user._id) return;
    setLoading(true);
    axios.get(`http://localhost:5000/api/wallet/${user._id}`)
      .then(res => {
        setBalance(res.data.balance);
        setTransactions(res.data.transactions);
        const u = JSON.parse(localStorage.getItem('vrx_user') || '{}');
        u.walletBalance = res.data.balance;
        localStorage.setItem('vrx_user', JSON.stringify(u));
        setLoading(false);
      }).catch(() => setLoading(false));
  };

  useEffect(() => { fetchWallet(); }, []);

  const handleAddMoney = async (amount) => {
    const val = amount || parseInt(addAmount);
    if (!val || val <= 0) return;
    setAdding(true);
    try {
      const res = await axios.post(`http://localhost:5000/api/wallet/${user._id}/add`, { amount: val, paymentMethod });
      setBalance(res.data.balance);
      const u = JSON.parse(localStorage.getItem('vrx_user') || '{}');
      u.walletBalance = res.data.balance;
      localStorage.setItem('vrx_user', JSON.stringify(u));
      setAddAmount('');
      setMessage(`₹${val} added successfully!`);
      setTimeout(() => setMessage(''), 3000);
      fetchWallet();
    } catch (err) {
      setMessage('Failed to add money');
    }
    setAdding(false);
  };

  return (
    <DashboardLayout activeTab="wallet">
      <div className="row g-4">
        {/* Balance Card */}
        <div className="col-lg-5">
          <div className="rounded-4 shadow-sm overflow-hidden" style={{ background: 'linear-gradient(135deg, #0F172A, #1E293B)' }}>
            <div className="p-5 text-white">
              <div className="d-flex align-items-center gap-2 mb-3">
                <i className="fa-solid fa-wallet fs-4" style={{ color: '#06B6D4' }}></i>
                <span className="text-uppercase small fw-bold" style={{ letterSpacing: '2px', color: '#94A3B8' }}>Wallet Balance</span>
              </div>
              <h1 className="display-4 fw-bold mb-0">₹{balance.toLocaleString()}</h1>
              <p className="mt-2 mb-0" style={{ color: '#64748B' }}><i className="fa-solid fa-circle-check me-1" style={{ color: '#10B981' }}></i> Active Wallet</p>
            </div>
            <div style={{ background: 'rgba(255,255,255,0.05)', padding: '20px 30px' }}>
              <div className="d-flex justify-content-between text-white">
                <div><small style={{ color: '#64748B' }}>Total Spent</small><br/><span className="fw-bold">₹{transactions.filter(t => t.type === 'ride_payment').reduce((a, t) => a + t.amount, 0)}</span></div>
                <div><small style={{ color: '#64748B' }}>Total Added</small><br/><span className="fw-bold">₹{transactions.filter(t => t.type === 'topup').reduce((a, t) => a + t.amount, 0)}</span></div>
                <div><small style={{ color: '#64748B' }}>Transactions</small><br/><span className="fw-bold">{transactions.length}</span></div>
              </div>
            </div>
          </div>

          {/* Add Money */}
          <div className="bg-white rounded-4 shadow-sm p-4 mt-4">
            <h5 className="fw-bold mb-3"><i className="fa-solid fa-plus-circle me-2 text-success"></i>Add Money</h5>
            {message && <div className={`alert ${message.includes('success') ? 'alert-success' : 'alert-danger'} py-2 small`}>{message}</div>}
            <div className="d-flex gap-2 mb-3 flex-wrap">
              {[100, 200, 500, 1000, 2000].map(amt => (
                <button key={amt} className="btn btn-outline-dark rounded-pill fw-bold px-3" onClick={() => handleAddMoney(amt)} disabled={adding}>
                  +₹{amt}
                </button>
              ))}
            </div>
            <div className="input-group mb-3">
              <span className="input-group-text bg-light border-0 fw-bold">₹</span>
              <input type="number" className="form-control p-3 bg-light border-0" placeholder="Enter custom amount" value={addAmount} onChange={e => setAddAmount(e.target.value)} />
              <button className="btn btn-primary-custom px-4" onClick={() => handleAddMoney()} disabled={adding || !addAmount}>
                {adding ? <i className="fa-solid fa-spinner fa-spin"></i> : 'Add'}
              </button>
            </div>
            <div className="d-flex gap-2">
              {[{ id: 'upi', icon: 'fa-mobile-screen', label: 'UPI' }, { id: 'card', icon: 'fa-credit-card', label: 'Card' }].map(m => (
                <button key={m.id} className={`btn flex-grow-1 rounded-3 p-2 ${paymentMethod === m.id ? 'btn-dark' : 'btn-outline-secondary'}`} onClick={() => setPaymentMethod(m.id)}>
                  <i className={`fa-solid ${m.icon} me-2`}></i>{m.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Transaction History */}
        <div className="col-lg-7">
          <div className="bg-white rounded-4 shadow-sm p-4">
            <h5 className="fw-bold mb-4"><i className="fa-solid fa-clock-rotate-left me-2 text-primary"></i>Transaction History</h5>
            {loading ? (
              <div className="text-center p-4"><div className="spinner-border text-primary"></div></div>
            ) : transactions.length === 0 ? (
              <div className="text-center p-5">
                <i className="fa-solid fa-receipt fs-1 text-muted mb-3" style={{ opacity: 0.3 }}></i>
                <p className="text-muted">No transactions yet. Add money to get started!</p>
              </div>
            ) : (
              <div className="d-flex flex-column gap-2">
                {transactions.map((tx, i) => (
                  <div key={tx._id || i} className="d-flex align-items-center gap-3 p-3 rounded-3" style={{ background: '#F8FAFC', transition: 'background 0.2s' }}
                    onMouseEnter={e => e.currentTarget.style.background = '#F1F5F9'}
                    onMouseLeave={e => e.currentTarget.style.background = '#F8FAFC'}>
                    <div style={{
                      width: '45px', height: '45px', borderRadius: '12px',
                      background: tx.type === 'topup' ? 'rgba(16,185,129,0.1)' : tx.type === 'refund' ? 'rgba(6,182,212,0.1)' : 'rgba(239,68,68,0.1)',
                      color: tx.type === 'topup' ? '#10B981' : tx.type === 'refund' ? '#06B6D4' : '#EF4444',
                      display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px', flexShrink: 0
                    }}>
                      <i className={`fa-solid ${tx.type === 'topup' ? 'fa-arrow-down' : tx.type === 'refund' ? 'fa-rotate-left' : 'fa-arrow-up'}`}></i>
                    </div>
                    <div className="flex-grow-1">
                      <h6 className="fw-bold mb-0">{tx.description || (tx.type === 'topup' ? 'Money Added' : 'Ride Payment')}</h6>
                      <small className="text-muted">{new Date(tx.createdAt).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}</small>
                    </div>
                    <h5 className={`fw-bold m-0 ${tx.type === 'topup' || tx.type === 'refund' ? 'text-success' : 'text-danger'}`}>
                      {tx.type === 'topup' || tx.type === 'refund' ? '+' : '-'}₹{tx.amount}
                    </h5>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
};

export default WalletPage;
